function miniMap(){
  // Fixed north-up field map. Bright paths show where the player has walked.
  const size=touchControls.enabled?Math.max(2,Math.min(4,Math.floor((H-240)/N))):Math.max(4,Math.min(9,Math.floor(W*.21/N),Math.floor((H-240)/N))),span=N*size;
  const ox=W-span-(touchControls.enabled?70:30),oy=touchControls.enabled?86:117,px=ox+player.x*size,py=oy+player.y*size;
  ctx.save();ctx.fillStyle='#071216ed';ctx.fillRect(ox-14,oy-35,span+28,span+(touchControls.enabled?94:113));
  ctx.strokeStyle='#c9ad6455';ctx.lineWidth=1;ctx.strokeRect(ox-14,oy-35,span+28,span+(touchControls.enabled?94:113));
  ctx.fillStyle='#d9c58b';ctx.font=touchControls.enabled?'bold 8px monospace':'bold 11px monospace';ctx.fillText('FIELD MAP',ox,oy-16);
  ctx.textAlign='right';ctx.font=touchControls.enabled?'8px monospace':'10px monospace';ctx.fillText('N ↑',ox+span,oy-16);ctx.textAlign='left';
  for(let y=0;y<N;y++)for(let x=0;x<N;x++){
    ctx.fillStyle=maze[y][x]?'#303d29':visited.has(`${x},${y}`)?'#c0b477':'#647578';
    ctx.fillRect(ox+x*size,oy+y*size,size,size);
  }
  // Entrance remains a stable landmark for orientation.
  ctx.strokeStyle='#e1b367';ctx.lineWidth=2;ctx.strokeRect(ox+size+1,oy+size+1,size-2,size-2);
  ctx.fillStyle='#b9edee30';ctx.beginPath();ctx.moveTo(px,py);
  ctx.arc(px,py,size*3,player.a-.45,player.a+.45);ctx.closePath();ctx.fill();
  ctx.save();ctx.translate(px,py);ctx.rotate(player.a);ctx.shadowColor='#000';ctx.shadowBlur=4;
  poly(ctx,[[8,0],[-5,-5],[-2,0],[-5,5]],'#efffff');ctx.restore();
  if(touchControls.enabled){
    // Stack the legend so its labels remain readable beside the action buttons.
    ctx.font='8px monospace';ctx.fillStyle='#efffff';ctx.fillText('▲ YOU',ox,oy+span+10);
    ctx.fillStyle='#c0b477';ctx.fillRect(ox,oy+span+17,5,5);ctx.fillText('EXPLORED',ox+9,oy+span+22);
    ctx.fillStyle='#e1b367';ctx.fillText('□ ENTRANCE',ox,oy+span+34);
  }else{
    ctx.font='10px monospace';ctx.fillStyle='#efffff';ctx.fillText('▲ YOU',ox,oy+span+17);
    ctx.fillStyle='#c0b477';ctx.fillRect(ox,oy+span+27,7,7);ctx.fillText('EXPLORED',ox+12,oy+span+34);
    ctx.textAlign='right';ctx.fillStyle='#a2b4b4';ctx.fillText('M HIDE',ox+span,oy+span+17);
    ctx.fillStyle='#e1b367';ctx.fillText('□ ENTRANCE',ox+span,oy+span+34);
  }
  drawLesterPing(ox,oy,size,span);ctx.restore();
}

